for k in range(2, 126):
    fib_list.append(fibonacci(k))

# Check for distinctness
if len(fib_list) == len(set(fib_list)):
    print("Verification Successful: All 124 Fibonacci numbers (F_2 to F_125) are distinct.")
else:
